// sp/sp_pago_orden.sp
    1  /*
    2   * Banco Ficticio S.A. - Reference application of the NexTI platform (fictitious, written for the repository).
    3   * Debits the account of a company for one payment order, charges the service commission and updates the order.
    4   * Nothing here comes from a real bank: names, tables and rules are invented to exercise the Sybase adapter.
    5   */
    6  create procedure dbo.sp_pago_orden
    7  (
    8      @i_orden            int,
    9      @i_empresa          int,
   10      @i_servicio         varchar(10),
   11      @i_tipo_cuenta      char(3),
   12      @i_cuenta           char(10),
   13      @i_valor            money,
   14      @i_canal            char(3)     = 'WEB',
   15      @i_fecha_proceso    datetime,
   16      @o_movimiento       int         = null output,
   17      @o_mensaje          varchar(120) = null output
   18  )
   19  as
   20  declare @w_return       int,
   21          @w_error        int,
   22          @w_tarifa       money,
   23          @w_comision     money,
   24          @w_total        money,
   25          @w_saldo        money,
   26          @w_estado       char(1),
   27          @w_separada     char(1),
   28          @w_rowcount     int
   29  
   30  select @w_return = 0,
   31         @o_mensaje = null
   32  
   33  /* RF-01: only current, savings and virtual accounts can be debited */
   34  if @i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')
   35  begin
   36      select @w_error = 50001,
   37             @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'
   38      goto ERROR
   39  end
   40  
   41  /* RF-02: the order must exist and be pending */
   42  select @w_estado = ord_estado
   43    from db_pagos..pg_orden
   44   where ord_numero = @i_orden
   45     and ord_empresa = @i_empresa
   46  
   47  if @@rowcount = 0
   48  begin
   49      select @w_error = 50002,
   50             @o_mensaje = 'ORDEN NO EXISTE'
   51      goto ERROR
   52  end
   53  
   54  if @w_estado <> 'P'
   55  begin
   56      select @w_error = 50003,
   57             @o_mensaje = 'ORDEN NO ESTA PENDIENTE'
   58      goto ERROR
   59  end
   60  
   61  /* RF-03: the tariff comes from the company table, else from the general service table */
   62  select @w_tarifa = tar_valor,
   63         @w_separada = tar_separada
   64    from db_admin..ad_tarifa_empresa
   65   where tar_empresa = @i_empresa
   66     and tar_servicio = @i_servicio
   67  
   68  if @@rowcount = 0
   69  begin
   70      select @w_tarifa = srv_tarifa,
   71             @w_separada = 'N'
   72        from db_admin..ad_servicio
   73       where srv_codigo = @i_servicio
   74  end
   75  
   76  if @w_tarifa is null
   77      select @w_tarifa = 0
   78  
   79  /* RF-04: web orders pay half the tariff; payroll never pays commission */
   80  if @i_canal = 'WEB'
   81      select @w_comision = round(@w_tarifa / 2, 2)
   82  else
   83      select @w_comision = @w_tarifa
   84  
   85  if @i_servicio = 'NOMINA'
   86      select @w_comision = 0
   87  
   88  /* RF-05: the total to debit includes the commission unless it is charged separately */
   89  if @w_separada = 'S'
   90      select @w_total = @i_valor
   91  else
   92      select @w_total = @i_valor + @w_comision
   93  
   94  /* RF-06: virtual accounts cannot go below zero; other accounts may overdraw up to 100.00 */
   95  select @w_saldo = cta_saldo
   96    from db_cuentas..ct_cuenta
   97   where cta_numero = @i_cuenta
   98     and cta_tipo = @i_tipo_cuenta
   99  
  100  if (@i_tipo_cuenta = 'VIR' and @w_saldo < @w_total)
  101     or (@i_tipo_cuenta <> 'VIR' and @w_saldo + 100.00 < @w_total)
  102  begin
  103      select @w_error = 50004,
  104             @o_mensaje = 'FONDOS INSUFICIENTES'
  105      goto ERROR
  106  end
  107  
  108  begin tran
  109  
  110  exec @w_return = db_cuentas..sp_debito
  111       @i_cuenta     = @i_cuenta,
  112       @i_tipo       = @i_tipo_cuenta,
  113       @i_valor      = @w_total,
  114       @i_referencia = 'PAGO ORDEN',
  115       @o_secuencial = @o_movimiento output
  116  
  117  if @w_return <> 0 or @@error <> 0
  118  begin
  119      rollback tran
  120      select @w_error = 50005,
  121             @o_mensaje = 'ERROR EN DEBITO'
  122      goto ERROR
  123  end
  124  
  125  /* RF-07: a separate commission is a second movement */
  126  if @w_separada = 'S' and @w_comision > 0
  127  begin
  128      exec @w_return = db_cuentas..sp_debito
  129           @i_cuenta     = @i_cuenta,
  130           @i_tipo       = @i_tipo_cuenta,
  131           @i_valor      = @w_comision,
  132           @i_referencia = 'COMISION PAGO'
  133  
  134      if @w_return <> 0
  135      begin
  136          rollback tran
  137          select @w_error = 50006,
  138                 @o_mensaje = 'ERROR EN COMISION'
  139          goto ERROR
  140      end
  141  end
  142  
  143  /* RF-08: the order is marked paid with the processing date and the commission charged */
  144  update db_pagos..pg_orden
  145     set ord_estado = 'A',
  146         ord_fecha_pago = @i_fecha_proceso,
  147         ord_comision = @w_comision
  148   where ord_numero = @i_orden
  149     and ord_empresa = @i_empresa
  150  
  151  select @w_error = @@error, @w_rowcount = @@rowcount
  152  
  153  if @w_error <> 0 or @w_rowcount = 0
  154  begin
  155      rollback tran
  156      select @w_error = 50007,
  157             @o_mensaje = 'ERROR ACTUALIZANDO ORDEN'
  158      goto ERROR
  159  end
  160  
  161  commit tran
  162  
  163  select @o_mensaje = 'PAGO REALIZADO'
  164  return 0
  165  
  166  ERROR:
  167  exec cobis..sp_cerror
  168       @t_from = 'sp_pago_orden',
  169       @i_num  = @w_error,
  170       @i_msg  = @o_mensaje
  171  return @w_error
  172  go

The legacy engine behaviour this program relies on (measured on the engine of the golden master):
- [high] select-assign-from-table (lines 42, 62, 70, 95; confirmed on the legacy engine): `select @v = col from t where ...` leaves @v unchanged when no row matches and keeps the LAST row when several match; it never fails. Target: Keep the previous value when the query returns nothing and take the last row when it returns several; do not throw on an empty or multiple result.
- [high] error-continues (lines 47, 68, 117, 151; not probed): A failing statement does not stop the procedure: execution goes on and the program decides with @@error and @@rowcount, which every statement resets. Target: Read the outcome of each statement right after it (rows affected, error) and continue as the program does; do not let an exception skip the code the legacy runs after the error.
- [high] nested-tran (lines 108, 119, 136, 155; confirmed on the legacy engine): Transactions nest by count (@@trancount); a ROLLBACK at any level rolls back everything and sets the count to 0. Target: Use one transaction for the whole program and roll it back entirely where the program rolls back.
- [medium] char-padding (lines 42, 54, 63, 71, 80, 89, 97, 98, 100, 101, 111, 112, 126, 129, 130; confirmed on the legacy engine): Comparisons ignore trailing spaces ('a' = 'a  ') and CHAR(n) values are padded with spaces to n. Target: Compare strings without their trailing spaces and pad or trim CHAR values as the golden master shows.
- [high] param-default-vs-null (lines 14, 16, 17; confirmed on the legacy engine): A parameter with a default takes it only when the caller omits the argument; an explicit NULL stays NULL and the default does not apply. Target: Distinguish an omitted argument (the default applies) from a null one (it stays null): a request field that is absent is not the same as one that is null.
- [high] callee-raiserror-continues (lines 110, 128, 167; confirmed on the legacy engine): An error raised inside a called procedure (raiserror) does not abort the caller: execution goes on, @@error is 0 after the exec, and only the return status (exec @rc = proc) carries the failure. Target: Read the status the called program returns and act on it as the legacy does; do not expect an exception from the call, and do not let one abort what the legacy continues.
