package com.bank.payments.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.CompanyTariff;
import com.bank.payments.domain.model.DebitResult;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.model.ServiceTariff;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.CompanyTariffRepository;
import com.bank.payments.domain.port.DebitGateway;
import com.bank.payments.domain.port.PaymentOrderRepository;
import com.bank.payments.domain.port.ServiceTariffRepository;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class PayOrderServiceTest {

    private static final LocalDateTime PROCESS_DATE = LocalDateTime.of(2024, 5, 31, 0, 0);

    record DebitCall(String account, String type, BigDecimal amount, String reference) {
    }

    record PaidCall(Integer order, Integer company, LocalDateTime date, BigDecimal commission) {
    }

    /** In-memory fakes of all ports, with recorded calls. */
    static final class Env {
        Optional<PaymentOrder> order = Optional.of(new PaymentOrder(100, 1, "P", null, null));
        Optional<CompanyTariff> companyTariff = Optional.empty();
        Optional<ServiceTariff> serviceTariff = Optional.empty();
        Optional<Account> account =
                Optional.of(new Account("1234567890", "AHO", new BigDecimal("1000.00")));
        Optional<DebitResult> debitResult = Optional.of(new DebitResult(0, 777));
        int commissionReturn = 0;
        int updateRows = 1;

        final List<String> calls = new ArrayList<>();
        final List<DebitCall> debits = new ArrayList<>();
        final List<DebitCall> commissionDebits = new ArrayList<>();
        final List<PaidCall> paid = new ArrayList<>();
        final List<String> orderLookups = new ArrayList<>();
        final List<String> companyTariffLookups = new ArrayList<>();
        final List<String> serviceTariffLookups = new ArrayList<>();
        final List<String> accountLookups = new ArrayList<>();

        PayOrderService service() {
            PaymentOrderRepository orders = new PaymentOrderRepository() {
                @Override
                public Optional<PaymentOrder> findByNumberAndCompany(Integer orderNumber, Integer companyId) {
                    calls.add("findOrder");
                    orderLookups.add(orderNumber + "/" + companyId);
                    return order;
                }

                @Override
                public int markAsPaid(Integer orderNumber, Integer companyId, LocalDateTime paymentDate,
                        BigDecimal commission) {
                    calls.add("markAsPaid");
                    paid.add(new PaidCall(orderNumber, companyId, paymentDate, commission));
                    return updateRows;
                }
            };
            CompanyTariffRepository companyTariffs = (companyId, serviceCode) -> {
                calls.add("findCompanyTariff");
                companyTariffLookups.add(companyId + "/" + serviceCode);
                return companyTariff;
            };
            ServiceTariffRepository serviceTariffs = serviceCode -> {
                calls.add("findServiceTariff");
                serviceTariffLookups.add(serviceCode);
                return serviceTariff;
            };
            AccountRepository accounts = (accountNumber, accountType) -> {
                calls.add("findAccount");
                accountLookups.add(accountNumber + "/" + accountType);
                return account;
            };
            DebitGateway gateway = new DebitGateway() {
                @Override
                public Optional<DebitResult> debit(String accountNumber, String accountType, BigDecimal amount,
                        String reference) {
                    calls.add("debit");
                    debits.add(new DebitCall(accountNumber, accountType, amount, reference));
                    return debitResult;
                }

                @Override
                public int debitCommission(String accountNumber, String accountType, BigDecimal amount,
                        String reference) {
                    calls.add("debitCommission");
                    commissionDebits.add(new DebitCall(accountNumber, accountType, amount, reference));
                    return commissionReturn;
                }
            };
            return new PayOrderService(orders, companyTariffs, serviceTariffs, accounts, gateway);
        }
    }

    private static PayOrderRequest request(String serviceCode, String accountType, String channel, String amount) {
        return new PayOrderRequest(100, 1, serviceCode, accountType, "1234567890",
                new BigDecimal(amount), channel, PROCESS_DATE);
    }

    private static PayOrderRequest defaultRequest() {
        return request("AGUA", "AHO", "VEN", "100.00");
    }

    private static void assertError(Env env, PayOrderRequest request, String code, String legacyCode,
            String message) {
        assertThatThrownBy(() -> env.service().execute(request))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError be = (BusinessError) e;
                    assertThat(be.code()).isEqualTo(code);
                    assertThat(be.legacyCode()).isEqualTo(legacyCode);
                    assertThat(be.getMessage()).isEqualTo(message);
                });
    }

    private static CompanyTariff companyTariff(String value, String separate) {
        return new CompanyTariff(1, "AGUA", value == null ? null : new BigDecimal(value), separate);
    }

    // ---- RULE-002 / RULE-003: account type ----

    @Test
    void account_type_not_allowed_is_rejected_with_50001_before_any_read() {
        Env env = new Env();
        assertError(env, request("AGUA", "PRE", "VEN", "100.00"),
                "ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        assertThat(env.calls).isEmpty();
    }

    @Test
    void account_type_check_comes_before_order_existence_check() {
        Env env = new Env();
        env.order = Optional.empty();
        assertError(env, request("AGUA", "PRE", "VEN", "100.00"),
                "ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        assertThat(env.calls).isEmpty();
    }

    @Test
    void account_type_cte_is_allowed() {
        Env env = new Env();
        PayOrderResponse r = env.service().execute(request("AGUA", "CTE", "VEN", "100.00"));
        assertThat(r.message()).isEqualTo("PAGO REALIZADO");
        assertThat(env.debits).hasSize(1);
    }

    @Test
    void account_type_aho_is_allowed() {
        Env env = new Env();
        PayOrderResponse r = env.service().execute(request("AGUA", "AHO", "VEN", "100.00"));
        assertThat(r.message()).isEqualTo("PAGO REALIZADO");
    }

    @Test
    void account_type_vir_is_allowed() {
        Env env = new Env();
        PayOrderResponse r = env.service().execute(request("AGUA", "VIR", "VEN", "100.00"));
        assertThat(r.message()).isEqualTo("PAGO REALIZADO");
    }

    @Test
    void account_type_check_is_case_sensitive_lowercase_rejected() {
        Env env = new Env();
        assertError(env, request("AGUA", "aho", "VEN", "100.00"),
                "ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
    }

    // ---- RULE-005: order exists ----

    @Test
    void order_not_found_is_rejected_with_50002() {
        Env env = new Env();
        env.order = Optional.empty();
        assertError(env, defaultRequest(), "ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        assertThat(env.calls).containsExactly("findOrder");
        assertThat(env.orderLookups).containsExactly("100/1");
    }

    // ---- RULE-004: order pending ----

    @Test
    void order_not_pending_is_rejected_with_50003() {
        Env env = new Env();
        env.order = Optional.of(new PaymentOrder(100, 1, "X", null, null));
        assertError(env, defaultRequest(), "ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        assertThat(env.calls).containsExactly("findOrder");
    }

    @Test
    void order_already_paid_status_a_is_rejected_with_50003() {
        Env env = new Env();
        env.order = Optional.of(new PaymentOrder(100, 1, "A", null, null));
        assertError(env, defaultRequest(), "ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
    }

    @Test
    void order_pending_status_p_proceeds() {
        Env env = new Env();
        PayOrderResponse r = env.service().execute(defaultRequest());
        assertThat(r.message()).isEqualTo("PAGO REALIZADO");
    }

    // ---- RULE-006: tariff lookup ----

    @Test
    void company_tariff_exists_is_used_and_service_tariff_is_not_read() {
        Env env = new Env();
        env.companyTariff = Optional.of(companyTariff("2.0000", "S"));
        env.serviceTariff = Optional.of(new ServiceTariff("AGUA", new BigDecimal("9.0000")));
        env.service().execute(request("AGUA", "AHO", "VEN", "100.00"));
        assertThat(env.companyTariffLookups).containsExactly("1/AGUA");
        assertThat(env.serviceTariffLookups).isEmpty();
        // separate charge 'S': total = amount; commission = full tariff 2.00
        assertThat(env.debits.get(0).amount()).isEqualByComparingTo("100.00");
        assertThat(env.commissionDebits).hasSize(1);
        assertThat(env.commissionDebits.get(0).amount()).isEqualByComparingTo("2.00");
    }

    @Test
    void fall_back_to_service_tariff_with_flag_n() {
        Env env = new Env();
        env.serviceTariff = Optional.of(new ServiceTariff("AGUA", new BigDecimal("1.5000")));
        env.service().execute(request("AGUA", "AHO", "VEN", "100.00"));
        assertThat(env.companyTariffLookups).containsExactly("1/AGUA");
        assertThat(env.serviceTariffLookups).containsExactly("AGUA");
        // flag 'N': commission added to the total, no second movement
        assertThat(env.debits.get(0).amount()).isEqualByComparingTo("101.50");
        assertThat(env.commissionDebits).isEmpty();
        assertThat(env.paid.get(0).commission()).isEqualByComparingTo("1.50");
    }

    @Test
    void fall_back_to_service_tariff_ignores_nothing_from_company_when_company_row_absent_even_if_service_flag_s_n_a() {
        Env env = new Env();
        env.serviceTariff = Optional.of(new ServiceTariff("AGUA", new BigDecimal("4.0000")));
        env.service().execute(request("AGUA", "AHO", "WEB", "100.00"));
        // WEB: 2.00 included in the total
        assertThat(env.debits.get(0).amount()).isEqualByComparingTo("102.00");
        assertThat(env.commissionDebits).isEmpty();
    }

    @Test
    void no_company_tariff_and_no_service_row_gives_tariff_zero() {
        Env env = new Env();
        PayOrderResponse r = env.service().execute(request("AGUA", "AHO", "VEN", "100.00"));
        assertThat(r.message()).isEqualTo("PAGO REALIZADO");
        assertThat(env.debits.get(0).amount()).isEqualByComparingTo("100.00");
