import java.util.Optional;
import org.junit.jupiter.api.Test;

class PayOrderServiceTest {

    private static final LocalDateTime PROCESS_DATE = LocalDateTime.of(2024, 5, 31, 0, 0);
    private static final String COMMISSION_REFERENCE = "COMISION PAGO";

    record DebitCall(String account, String type, BigDecimal amount, String reference) {
    }

    record PaidCall(Integer order, Integer company, LocalDateTime date, BigDecimal commission) {
    }

    /** In-memory fakes of all ports, with recorded calls. */
    static final class Env {
        Optional<PaymentOrder> order = Optional.of(new PaymentOrder(100, 1, "P", null, null));
        Optional<CompanyTariff> companyTariff = Optional.empty();
        Optional<ServiceTariff> serviceTariff = Optional.empty();
        Optional<Account> account =
                Optional.of(new Account("1234567890", "AHO", new BigDecimal("1000.00")));
        Optional<DebitResult> debitResult = Optional.of(new DebitResult(0, 777));
        int commissionReturn = 0;
        int updateRows = 1;

        final List<String> calls = new ArrayList<>();
        final List<DebitCall> debits = new ArrayList<>();
        final List<DebitCall> commissionDebits = new ArrayList<>();
        final List<PaidCall> paid = new ArrayList<>();
        final List<String> orderLookups = new ArrayList<>();
        final List<String> companyTariffLookups = new ArrayList<>();
        final List<String> serviceTariffLookups = new ArrayList<>();
        final List<String> accountLookups = new ArrayList<>();

        PayOrderService service() {
            PaymentOrderRepository orders = new PaymentOrderRepository() {
                @Override
                public Optional<PaymentOrder> findByNumberAndCompany(Integer orderNumber, Integer companyId) {
                    calls.add("findOrder");
                    orderLookups.add(orderNumber + "/" + companyId);
                    return order;
                }

                @Override
                public int markAsPaid(Integer orderNumber, Integer companyId, LocalDateTime paymentDate,
                        BigDecimal commission) {
                    calls.add("markAsPaid");
                    paid.add(new PaidCall(orderNumber, companyId, paymentDate, commission));
                    return updateRows;
                }
            };
            CompanyTariffRepository companyTariffs = (companyId, serviceCode) -> {
                calls.add("findCompanyTariff");
                companyTariffLookups.add(companyId + "/" + serviceCode);
                return companyTariff;
            };
            ServiceTariffRepository serviceTariffs = serviceCode -> {
                calls.add("findServiceTariff");
                serviceTariffLookups.add(serviceCode);
                return serviceTariff;
            };
            AccountRepository accounts = (accountNumber, accountType) -> {
                calls.add("findAccount");
                accountLookups.add(accountNumber + "/" + accountType);
                return account;
            };
            DebitGateway gateway = new DebitGateway() {
                @Override
                public Optional<DebitResult> debit(String accountNumber, String accountType, BigDecimal amount,
                        String reference) {
                    DebitCall call = new DebitCall(accountNumber, accountType, amount, reference);
                    if (COMMISSION_REFERENCE.equals(reference)) {
                        // the program debits the separate commission (second sp_debito call) through the same port
                        calls.add("debitCommission");
                        commissionDebits.add(call);
                        return Optional.of(new DebitResult(commissionReturn, null));
                    }
                    calls.add("debit");
                    debits.add(call);
                    return debitResult;
                }

                @Override
                public int debitCommission(String accountNumber, String accountType, BigDecimal amount,
                        String reference) {
                    calls.add("debitCommission");
                    commissionDebits.add(new DebitCall(accountNumber, accountType, amount, reference));
                    return commissionReturn;
                }
            };
            return new PayOrderService(orders, companyTariffs, serviceTariffs, accounts, gateway);
        }
    }

    private static PayOrderRequest request(String serviceCode, String accountType, String channel, String amount) {
        return new PayOrderRequest(100, 1, serviceCode, accountType, "1234567890",
                new BigDecimal(amount), channel, PROCESS_DATE);
    }

    private static PayOrderRequest defaultRequest() {
        return request("AGUA", "AHO", "VEN", "100.00");
    }

    private static void assertError(Env env, PayOrderRequest request, String code, String legacyCode,
            String message) {
        assertThatThrownBy(() -> env.service().execute(request))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError be = (BusinessError) e;
                    assertThat(be.code()).isEqualTo(code);
                    assertThat(be.legacyCode()).isEqualTo(legacyCode);
                    assertThat(be.getMessage()).isEqualTo(message);
                });
    }

    private static CompanyTariff companyTariff(String value, String separate) {
        return new CompanyTariff(1, "AGUA", value == null ? null : new BigDecimal(value), separate);
    }

