    // ---- RULE-006: tariff lookup ----

    @Test
    void company_tariff_exists_is_used_and_service_tariff_is_not_read() {
        Env env = new Env();
        env.companyTariff = Optional.of(companyTariff("2.0000", "S"));
        env.serviceTariff = Optional.of(new ServiceTariff("AGUA", new BigDecimal("9.0000")));
        env.service().execute(request("AGUA", "AHO", "VEN", "100.00"));
        assertThat(env.companyTariffLookups).containsExactly("1/AGUA");
        assertThat(env.serviceTariffLookups).isEmpty();
        // separate charge 'S': total = amount; commission = full tariff 2.00
        assertThat(env.debits.get(0).amount()).isEqualByComparingTo("100.00");
        assertThat(env.commissionDebits).hasSize(1);
        assertThat(env.commissionDebits.get(0).amount()).isEqualByComparingTo("2.00");
    }

    @Test
    void fall_back_to_service_tariff_with_flag_n() {
        Env env = new Env();
        env.serviceTariff = Optional.of(new ServiceTariff("AGUA", new BigDecimal("1.5000")));
        env.service().execute(request("AGUA", "AHO", "VEN", "100.00"));
        assertThat(env.companyTariffLookups).containsExactly("1/AGUA");
        assertThat(env.serviceTariffLookups).containsExactly("AGUA");
        // flag 'N': commission added to the total, no second movement
        assertThat(env.debits.get(0).amount()).isEqualByComparingTo("101.50");
        assertThat(env.commissionDebits).isEmpty();
        assertThat(env.paid.get(0).commission()).isEqualByComparingTo("1.50");
